{
  "segment_function": "Research question and critical theoretical approach regarding human alienation and Arendtian citizenship",
  "claims": [
    {
      "claim": "The concept of citizenship in Hannah Arendt's thought can be employed as an alternative to counter the current crisis of human world-alienation.",
      "claim_type": "author_position",
      "supporting_excerpt": "ﺗﻮان از اﯾﻦ ﻣﻔﻬﻮم ﺑﻪ ﻋﻨﻮان ﯾﮏ آﻟﺘﺮﻧـﺎﺗﯿﻮ در ﻣﻘﺎﺑـﻞ  ﻣﯽ  ﻧﺸﺎن داد ﮐﻪ، در اداﻣﻪ ﺧﻮاﻫﺪ آﻣﺪ  در ﺧﻮاﻧﺸـﯽ اﻧﺘﻘـﺎدي از ﻣﻔﻬـﻮم  . ﺑﻬﺮه ﺟﺴﺖ، اﺳﺖﺑﺤﺮان ﺣﺎﺿﺮ ﮐﻪ از ﺟﻬﺎن ﺑﯿﮕﺎﻧﮕﯽ ﺑﺸﺮ  ﮐﻮﺷﺶ ﺷﺪ ﺗﺎ وﺟﻮه ﮔﻮﻧﺎﮔﻮن اﯾﻦ ﻧﻮع ﺷﻬﺮوﻧﺪي ، ﺷﻬﺮوﻧﺪي و از ﻣﯿﺎن ﻣﺘﻮن ﮔﻮﻧﺎﮔﻮن آرﻧﺖ",
      "support_kind": "direct",
      "qualifications": [
        "Through a critical reading of Arendt's texts and her interpreters"
      ],
      "confidence": 0.95
    }
  ],
  "definitions": [
    {
      "term": "ﺷﻬﺮوﻧﺪي",
      "definition": "ﺗﺮﮐﯿﺒـﯽ از ﺣﻘـﻮق و وﻇـﺎﯾﻒ ﻣـﺪﻧﯽ و ﺳﯿﺎﺳـﯽ  و  ﺟﺎﻣﻌـﻪ   يﺗﻤـﺎﻣﯽ اﻋﻀـﺎ   ﺑﻪﺷﺄن و ﻋﻀﻮﯾﺖ اﺟﺘﻤﺎﻋﯽ ، ﻣﺜﺎﺑﻪ ﻧﻮﻋﯽ ﭘﺎﯾﮕﺎه اﺟﺘﻤﺎﻋﯽ اﺳﺖ"
    }
  ],
  "distinctions": [],
  "examples": [],
  "objections": [],
  "responses": [],
  "references_to_other_sections": [],
  "unresolved_context": [],
  "must_not_be_lost": [
    "Arendt's perspective on modern human alienation and the normative alternative of citizenship."
  ]
}

